'use client'

import Link from 'next/link'
import Image from 'next/image'
import { Users, Eye, Film } from 'lucide-react'

export interface ChannelStats {
    channel_id: string
    channel_name: string
    channel_url: string | null
    channel_username: string | null
    video_count: number
    total_views: number
    total_likes: number
    subscriber_count: number
    latest_video_date: string | null
    sample_thumbnail: string | null
}

function formatNumber(num: number): string {
    if (num >= 1_000_000) return `${(num / 1_000_000).toFixed(1)}M`
    if (num >= 1_000) return `${(num / 1_000).toFixed(1)}K`
    return num.toString()
}

export function ChannelCard({ channel }: { channel: ChannelStats }) {
    return (
        <Link
            href={`/channel/${channel.channel_id}`}
            className="group relative flex flex-col overflow-hidden rounded-2xl border border-slate-200/60 bg-white shadow-sm hover:shadow-lg hover:border-blue-200/60 transition-all duration-300"
        >
            {/* Thumbnail */}
            <div className="relative aspect-video w-full overflow-hidden bg-slate-100">
                {channel.sample_thumbnail ? (
                    <Image
                        src={channel.sample_thumbnail}
                        alt={channel.channel_name}
                        fill
                        className="object-cover group-hover:scale-105 transition-transform duration-500"
                        sizes="(max-width: 640px) 100vw, (max-width: 1024px) 50vw, 25vw"
                    />
                ) : (
                    <div className="flex h-full items-center justify-center">
                        <Film className="w-10 h-10 text-slate-300" />
                    </div>
                )}
                {/* Gradient overlay */}
                <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-black/10 to-transparent" />
                {/* Video count badge */}
                <div className="absolute bottom-2.5 left-2.5 flex items-center gap-1.5 rounded-lg bg-black/50 backdrop-blur-sm px-2.5 py-1">
                    <Film className="w-3.5 h-3.5 text-white" />
                    <span className="text-xs font-semibold text-white">{channel.video_count} videos</span>
                </div>
            </div>

            {/* Info */}
            <div className="flex flex-col gap-2 p-4">
                {/* Channel name + avatar */}
                <div className="flex items-center gap-2.5">
                    <div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-gradient-to-br from-blue-500 to-indigo-600 text-white text-sm font-bold shadow-sm">
                        {channel.channel_name.charAt(0).toUpperCase()}
                    </div>
                    <h3 className="text-sm font-semibold text-slate-900 leading-tight group-hover:text-blue-600 transition-colors line-clamp-2">
                        {channel.channel_name}
                    </h3>
                </div>

                {/* Stats row */}
                <div className="flex items-center gap-3 text-xs text-slate-500">
                    <span className="flex items-center gap-1">
                        <Eye className="w-3.5 h-3.5" />
                        {formatNumber(channel.total_views)} views
                    </span>
                    {channel.subscriber_count > 0 && (
                        <span className="flex items-center gap-1">
                            <Users className="w-3.5 h-3.5" />
                            {formatNumber(channel.subscriber_count)}
                        </span>
                    )}
                </div>
            </div>
        </Link>
    )
}
